// Keep rows whose follow_up_due has passed and that haven't been followed up yet,
// and that were actually sent.
const today = new Date().toISOString().slice(0, 10);
return $input.all().filter((i) => {
  const due = (i.json.follow_up_due || '').toString().slice(0, 10);
  const done = (i.json.followed_up || '').toString().trim();
  const status = (i.json.status || '').toString().toLowerCase();
  return due && due <= today && !done && status === 'sent';
});

